        appointment.email,

      telephone:
        appointment.telephone
    },

    text
  }
}];

return [{
  json: {
    ...$json,
    text:
      "🗑️ **Annulation d'un rendez-vous**\n\n" +
      "Pour continuer, indiquez votre token de gestion."
  }
}];

const current = { ...$json };

let previous = {};

try {
  previous =
    $('Joindre tentative de session').item.json ?? {};
} catch (e) {
  try {
    previous =
      $('Charger état conversation').item.json ?? {};
  } catch (e2) {
    previous = {};
  }
}

// ======================================================
// 1. UTILITAIRES
// ======================================================

function hasValue(value) {
  return (
    value !== null &&
    value !== undefined &&
    value !== '' &&
    value !== 'null' &&
    value !== 'undefined'
  );
}

function pick(newValue, oldValue) {

  if (hasValue(newValue)) {
    return newValue;
  }

  if (hasValue(oldValue)) {
    return oldValue;
  }

  return null;
}

function normalizeSlots(value) {

  if (!value) {
    return [];
  }

  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'string') {

    try {
      const parsed = JSON.parse(value);

      return Array.isArray(parsed)
        ? parsed
        : [];

    } catch (e) {
      return [];
    }
  }

  return [];
}

function isValidUUID(value) {

  if (!value) {
    return false;
  }

  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
    .test(String(value).trim());
}

// ======================================================
// 2. MESSAGE COURANT
// ======================================================

const originalMessage =
  current.originalMessage ?? '';

const message =
  String(originalMessage)
    .trim()
    .toLowerCase();

// ======================================================
// 3. ETAT PRECEDENT
// ======================================================

const previousPendingAction =
  previous.pending_action ??
  null;

const previousConversationStep =
  previous.conversation_step ??
  null;

// ======================================================
// 4. INTENTION DU MESSAGE COURANT
// ======================================================
//
// current.intent vient normalement de "Parser intention".
// On considère donc cette valeur comme l'intention détectée
// sur le message ACTUEL.
//
// ======================================================

let currentIntent =
  current.intent ??
  current.llmIntent ??
  'GENERAL';

// ------------------------------------------------------
// Sécurisation avec quelques règles textuelles explicites
// ------------------------------------------------------

// ANNULATION

if (
  /\bannul(er|ation|e|ez)?\b/i.test(message)
) {

  currentIntent =
    'CANCEL_APPOINTMENT';
}

// REPLANIFICATION

else if (
  /\b(replanif|replanifier|replanification|déplacer|deplacer)\b/i
    .test(message) ||
  /\bchanger\b.*\b(rendez-vous|rdv)\b/i
    .test(message)
) {

  currentIntent =
    'RESCHEDULE_APPOINTMENT';
}

// CONSULTATION

else if (
  /\b(consulter|voir|retrouver)\b.*\b(rendez-vous|rdv)\b/i
    .test(message)
) {

  currentIntent =
    'GET_APPOINTMENT';
}

// CREATION

else if (
  /\b(prendre|réserver|reserver|créer|creer)\b.*\b(rendez-vous|rdv|créneau|creneau)\b/i
    .test(message)
) {

  currentIntent =
    'CREATE_APPOINTMENT';
}

// ======================================================
// 5. INTENTIONS METIER
// ======================================================

const businessIntents = [
  'CREATE_APPOINTMENT',
  'GET_APPOINTMENT',
  'CANCEL_APPOINTMENT',
  'RESCHEDULE_APPOINTMENT'
];

const hasExplicitBusinessIntent =
  businessIntents.includes(currentIntent);

// ======================================================
// 6. DETECTION D'UN REDEMARRAGE EXPLICITE
// ======================================================
//
// Problème traité :
//
// mémoire :
// CREATE_APPOINTMENT / READY_CREATE_SEARCH
//
// utilisateur :
// "Je souhaite prendre rendez-vous pour renouveler
// mon passeport"
//
// CREATE == CREATE ne suffit pas pour conclure qu'il
// continue l'ancienne création.
//
// Ici nous reconnaissons une NOUVELLE demande explicite.
//
// ======================================================

// ------------------------------------------------------
// Nouvelle création explicite
// ------------------------------------------------------

const explicitCreateRestart =
  currentIntent === 'CREATE_APPOINTMENT' &&
  (
    /\b(?:je\s+)?(?:souhaite|veux|voudrais|aimerais)\b.*\b(?:prendre|réserver|reserver|créer|creer)\b.*\b(?:rendez-vous|rdv)\b/i
      .test(message)
    ||
    /\b(?:prendre|réserver|reserver|créer|creer)\b.*\b(?:un\s+)?(?:rendez-vous|rdv)\b/i
      .test(message)
  );

// ------------------------------------------------------
// Nouvelle replanification explicite
// ------------------------------------------------------

const explicitRescheduleRestart =
  currentIntent === 'RESCHEDULE_APPOINTMENT' &&
  (
    /\b(?:je\s+)?(?:souhaite|veux|voudrais|aimerais)\b.*\b(?:replanifier|déplacer|deplacer)\b.*\b(?:rendez-vous|rdv)\b/i
      .test(message)
    ||
    /\b(?:replanifier|déplacer|deplacer)\b.*\b(?:mon\s+)?(?:rendez-vous|rdv)\b/i
      .test(message)
  );

// ------------------------------------------------------
// Nouvelle annulation explicite
// ------------------------------------------------------

const explicitCancelRestart =
  currentIntent === 'CANCEL_APPOINTMENT' &&
  (
    /\b(?:je\s+)?(?:souhaite|veux|voudrais|aimerais)\b.*\bannuler\b.*\b(?:rendez-vous|rdv)\b/i
      .test(message)
    ||
    /\bannuler\b.*\b(?:mon\s+)?(?:rendez-vous|rdv)\b/i
      .test(message)
  );

// ------------------------------------------------------
// Nouvelle consultation explicite
// ------------------------------------------------------

const explicitGetRestart =
  currentIntent === 'GET_APPOINTMENT' &&
  (
    /\b(?:je\s+)?(?:souhaite|veux|voudrais|aimerais)\b.*\b(?:consulter|voir|retrouver)\b.*\b(?:rendez-vous|rdv)\b/i
      .test(message)
    ||
    /\b(?:consulter|retrouver)\b.*\b(?:mon\s+)?(?:rendez-vous|rdv)\b/i
      .test(message)
  );

const createFlowLocked =
  ['AWAIT_CREATE_CONFIRMATION', 'CREATE_UNCERTAIN', 'CREATE_IN_PROGRESS'].includes(previous.conversation_step)
  || (
    previous.openAttempt
    && ['AWAITING_CONFIRMATION', 'SUBMITTING', 'UNCERTAIN'].includes(previous.openAttempt.status)
  );

const explicitRestart =
  !createFlowLocked &&
  (
    explicitCreateRestart ||
    explicitRescheduleRestart ||
    explicitCancelRestart ||
    explicitGetRestart
  );

// ======================================================
// 7. CHANGEMENT D'ACTION
// ======================================================
//
// CAS 1 :
// previous = RESCHEDULE
// current  = CREATE
// => changement
//
// CAS 2 :
// previous = CREATE
// current  = CREATE
// message = "Je souhaite prendre un rendez-vous"
// => redémarrage explicite
//
// CAS 3 :
// previous = RESCHEDULE
// current = GENERAL
// message = "Oui"
// => continuation
//
// ======================================================

const actionChanged =
  !createFlowLocked &&
  hasExplicitBusinessIntent &&
  hasValue(previousPendingAction) &&
  (
    currentIntent !== previousPendingAction ||
    explicitRestart
  );

// ======================================================
// 8. DEMARRAGE D'UNE PREMIERE ACTION
// ======================================================

const startingNewAction =
  !createFlowLocked &&
  hasExplicitBusinessIntent &&
  !hasValue(previousPendingAction);

// ======================================================
// 9. CONTINUATION DE L'ACTION PRECEDENTE
// ======================================================

const continuingPreviousAction =
  hasValue(previousPendingAction) &&
  !actionChanged &&
  !explicitRestart;

// ======================================================
// 10. CRENEAUX MEMORISES
// ======================================================

const previousAvailableSlots =
  normalizeSlots(
    previous.available_slots
  );

// ======================================================
// 11. VARIABLES DE SORTIE
// ======================================================

let intent =
  currentIntent;

let service =
  null;

let site =
  null;

let dateDebut =
  null;

let dateFin =
  null;

let slotId =
  null;

let token =
  null;

let newSlotId =
  null;

let selectedSlotIndex =
  null;

let selectedSlot =
  null;

let availableSlots =
  [];

let reference =
  null;

let nom =
  null;

let prenom =
  null;

let email =
  null;

let telephone =
  null;

// ======================================================
// 12. NOUVELLE ACTION / REDEMARRAGE / CHANGEMENT
// ======================================================
//
// REGLE PRINCIPALE :
//
// Si une nouvelle action commence, nous ne fusionnons
// PAS les anciennes informations métier.
//
// Nous utilisons uniquement ce que "Parser intention"
// a réellement extrait du message courant.
//
// ======================================================

const slotSelectionFromAvailability =
  !createFlowLocked &&
  !explicitRestart &&
  previousPendingAction === 'GET_AVAILABILITY' &&
  currentIntent === 'CREATE_APPOINTMENT' &&
  hasValue(current.selectedSlotIndex);

if (
  (actionChanged || startingNewAction) &&
  slotSelectionFromAvailability
) {

  // Transition GET_AVAILABILITY -> CREATE via « Je prends le N » :
  // conserver critères et créneaux mémorisés, puis résoudre l'UUID.
  intent =
    'CREATE_APPOINTMENT';

  service =
    pick(
      current.service,
      previous.service
    );

  site =
    pick(
      current.site,
      previous.site
    );

  dateDebut =
    pick(
      current.dateDebut,
      previous.date_debut
    );

  dateFin =
    pick(
      current.dateFin,
      previous.date_fin
    );

  slotId =
    hasValue(current.slotId)
      ? current.slotId
      : null;

  token =
    null;

  newSlotId =
    null;

  selectedSlotIndex =
    current.selectedSlotIndex;

  reference =
    hasValue(current.reference)
      ? current.reference
      : null;

  nom =
    hasValue(current.nom)
      ? current.nom
      : null;

  prenom =
    hasValue(current.prenom)
      ? current.prenom
      : null;

  email =
    hasValue(current.email)
      ? current.email
      : null;

  telephone =
    hasValue(current.telephone)
      ? current.telephone
      : null;

  availableSlots =
    previousAvailableSlots;

  selectedSlot =
    null;
}

else if (
  actionChanged ||
  startingNewAction
) {

  intent =
    currentIntent;

  // ----------------------------------------------------
  // Service
  // ----------------------------------------------------

  service =
    hasValue(current.service)
      ? current.service
      : null;

  // ----------------------------------------------------
  // Site
  // ----------------------------------------------------

  site =
    hasValue(current.site)
      ? current.site
      : null;

  // ----------------------------------------------------
  // Dates
  // ----------------------------------------------------

  dateDebut =
    hasValue(current.dateDebut)
      ? current.dateDebut
      : null;

  dateFin =
    hasValue(current.dateFin)
      ? current.dateFin
      : null;

  // ----------------------------------------------------
  // Identifiants
  // ----------------------------------------------------

  slotId =
    hasValue(current.slotId)
      ? current.slotId
      : null;

  token =
    hasValue(current.token)
      ? current.token
      : null;

  newSlotId =
    hasValue(current.newSlotId)
      ? current.newSlotId
      : null;

  selectedSlotIndex =
    hasValue(current.selectedSlotIndex)
      ? current.selectedSlotIndex
      : null;

  // ----------------------------------------------------
  // Référence
  // ----------------------------------------------------

  reference =
    hasValue(current.reference)
      ? current.reference
      : null;

  // ----------------------------------------------------
  // Informations personnelles
  // ----------------------------------------------------

  nom =
    hasValue(current.nom)
      ? current.nom
      : null;

  prenom =
    hasValue(current.prenom)
      ? current.prenom
      : null;

  email =
    hasValue(current.email)
      ? current.email
      : null;

  telephone =
    hasValue(current.telephone)
      ? current.telephone
      : null;

  // ----------------------------------------------------
  // Une nouvelle action ne récupère jamais les anciens
  // créneaux.
  // ----------------------------------------------------

  availableSlots =
    [];

  selectedSlot =
    null;

  // ----------------------------------------------------
  // CREATE
  // ----------------------------------------------------

  if (
    currentIntent === 'CREATE_APPOINTMENT'
  ) {

    // Une création n'utilise jamais le token d'un
    // rendez-vous existant.

    token =
      null;

    // newSlotId appartient à RESCHEDULE.

    newSlotId =
      null;
  }

  // ----------------------------------------------------
  // RESCHEDULE
  // ----------------------------------------------------

  if (
    currentIntent === 'RESCHEDULE_APPOINTMENT'
  ) {

    // slotId appartient à CREATE.
    // Pour RESCHEDULE, le nouveau créneau ira dans
    // newSlotId.

    slotId =
      null;
  }
}

// ======================================================
// 13. CONTINUATION DE LA MEME ACTION
// ======================================================
//
// C'est uniquement ici que nous avons le droit de faire:
//
// nouvelle valeur ?? ancienne valeur
//
// ======================================================

else if (
  continuingPreviousAction
) {

  // ----------------------------------------------------
  // L'action précédente reste prioritaire
  // ----------------------------------------------------

  intent =
    previousPendingAction;

  // ----------------------------------------------------
  // Service
  // ----------------------------------------------------

  service =
    pick(
      current.service,
      previous.service
    );

  // ----------------------------------------------------
  // Site
  // ----------------------------------------------------

  site =
    pick(
      current.site,
      previous.site
    );

  // ----------------------------------------------------
  // Dates
  // ----------------------------------------------------

  dateDebut =
    pick(
      current.dateDebut,
      previous.date_debut
    );

  dateFin =
    pick(
      current.dateFin,
      previous.date_fin
    );

  // ----------------------------------------------------
  // Identifiants
  // ----------------------------------------------------

  slotId =
    pick(
      current.slotId,
      previous.slot_id
    );

  token =
    pick(
      current.token,
      previous.token
    );

  newSlotId =
    pick(
      current.newSlotId,
      previous.new_slot_id
    );

  // ----------------------------------------------------
  // Référence
  // ----------------------------------------------------

  reference =
    pick(
      current.reference,
      previous.reference
    );

  // ----------------------------------------------------
  // Informations personnelles
  // ----------------------------------------------------

  nom =
    pick(
      current.nom,
      previous.nom
    );

  prenom =
    pick(
      current.prenom,
      previous.prenom
    );

  email =
    pick(
      current.email,
      previous.email
    );

  telephone =
    pick(
      current.telephone,
      previous.telephone
    );

  // ----------------------------------------------------
  // Sélection
  // ----------------------------------------------------

  selectedSlotIndex =
    pick(
      current.selectedSlotIndex,
      previous.selected_slot_index
    );

  availableSlots =
    previousAvailableSlots;
}

// ======================================================
// 14. AUCUNE ACTION METIER ACTIVE
// ======================================================

else {

  // GET_AVAILABILITY / GENERAL sans pending_action :
  // conserver la mémoire valide déjà enregistrée.
  intent =
    currentIntent;

  service =
    pick(
      current.service,
      previous.service
    );

  site =
    pick(
      current.site,
      previous.site
    );

  dateDebut =
    pick(
      current.dateDebut,
      previous.date_debut
    );

  dateFin =
    pick(
      current.dateFin,
      previous.date_fin
    );

  slotId =
    pick(
      current.slotId,
      previous.slot_id
    );

  token =
    pick(
      current.token,
      previous.token
    );

  newSlotId =
    pick(
      current.newSlotId,
      previous.new_slot_id
    );

  selectedSlotIndex =
    pick(
      current.selectedSlotIndex,
      previous.selected_slot_index
    );

  reference =
    pick(
      current.reference,
      previous.reference
    );

  nom =
    pick(
      current.nom,
      previous.nom
    );

  prenom =
    pick(
      current.prenom,
      previous.prenom
    );

  email =
    pick(
      current.email,
      previous.email
    );

  telephone =
    pick(
      current.telephone,
      previous.telephone
    );

  availableSlots =
    previousAvailableSlots;
}

// ======================================================
// 15. CONVERSION DU NUMERO DE CRENEAU
// ======================================================
//
// Exemple:
//
// utilisateur : "Je prends le 2"
//
// Si action = CREATE
//     -> slotId
//
// Si action = RESCHEDULE
//     -> newSlotId
//
// IMPORTANT :
// Le choix "2" ne change jamais à lui seul l'intention.
//
// ======================================================

if (
  selectedSlotIndex !== null &&
  selectedSlotIndex !== undefined &&
  Array.isArray(availableSlots) &&
  availableSlots.length > 0
) {

  const numericIndex =
    Number(selectedSlotIndex);

  if (
    Number.isInteger(numericIndex) &&
    numericIndex >= 1 &&
    numericIndex <= availableSlots.length
  ) {

    selectedSlot =
      availableSlots[numericIndex - 1];

    const selectedId =
      selectedSlot?.id ??
      selectedSlot?.slotId ??
      null;

    if (
      selectedId &&
      isValidUUID(selectedId)
    ) {

      // ------------------------------------------------
      // REPLANIFICATION
      // ------------------------------------------------

      if (
        previousPendingAction ===
          'RESCHEDULE_APPOINTMENT' ||
        intent ===
          'RESCHEDULE_APPOINTMENT'
      ) {

        newSlotId =
          String(selectedId).trim();

        slotId =
          null;

        intent =
          'RESCHEDULE_APPOINTMENT';
      }

      // ------------------------------------------------
      // CREATION
      // ------------------------------------------------

      else if (
        previousPendingAction ===
          'CREATE_APPOINTMENT' ||
        intent ===
          'CREATE_APPOINTMENT'
      ) {

        slotId =
          String(selectedId).trim();

        newSlotId =
          null;

        intent =
          'CREATE_APPOINTMENT';
      }
    }
  }
}

// ======================================================
// 16. DISPONIBILITE HORS ACTION MULTI-TOUR
// ======================================================
//
// On évite de convertir une CREATE ou une RESCHEDULE
// active en GET_AVAILABILITY dans ce nœud.
//
// "Gérer collecte progressive" décidera quand une
// recherche de créneaux est réellement prête.
//
// ======================================================

if (
  !hasValue(previousPendingAction) &&
  !hasExplicitBusinessIntent
) {

  if (
    service &&
    site &&
    (
      dateDebut ||
      dateFin ||
      /\b(disponibilit|créneau|creneau|période|periode|date)\b/i
        .test(message)
    )
  ) {

    intent =
      'GET_AVAILABILITY';
  }
}

// ======================================================
// 17. SECURITE CREATE_APPOINTMENT
// ======================================================

if (
  intent === 'CREATE_APPOINTMENT'
) {

  // Un CREATE n'utilise pas le token de gestion
  // d'un ancien rendez-vous.

  token =
    null;

  // newSlotId est réservé à la replanification.

  newSlotId =
    null;
}

// ======================================================
// 18. SECURITE RESCHEDULE_APPOINTMENT
// ======================================================

if (
  intent === 'RESCHEDULE_APPOINTMENT'
) {

  // slotId représente le créneau choisi pour CREATE.
  // newSlotId représente le nouveau créneau de RESCHEDULE.

  slotId =
    null;
}

// ======================================================
// 19. RESULTAT FINAL
// ======================================================

return [{
  json: {

    // --------------------------------------------------
    // Session
    // --------------------------------------------------

    sessionId:
      current.sessionId ??
      previous.session_id ??
      null,

    // --------------------------------------------------
    // Action
    // --------------------------------------------------

    intent,

    // --------------------------------------------------
    // Critères
    // --------------------------------------------------

    service,
    site,

    dateDebut,
    dateFin,

    // --------------------------------------------------
    // Identifiants
    // --------------------------------------------------

    slotId,
    token,
    newSlotId,

    // --------------------------------------------------
    // Sélection
    // --------------------------------------------------

    selectedSlotIndex,

    selectedSlot,

    availableSlots,

    // --------------------------------------------------
    // Rendez-vous / personne
    // --------------------------------------------------

    reference,

    nom,
    prenom,
    email,
    telephone,

    // --------------------------------------------------
    // Message
    // --------------------------------------------------

    originalMessage,

    confidence:
      current.confidence ?? 0,

    llmIntent:
      current.llmIntent ??
      current.intent ??
      null,

    // ==================================================
    // DEBUG TEMPORAIRE
    // ==================================================
    //
    // Gardez ce bloc pendant nos tests.
    // Nous pourrons le supprimer lorsque CREATE /
    // CANCEL / GET / RESCHEDULE seront tous validés.
    //
    // ==================================================

    memoryDebug: {

      // ----------------------------------------------
      // Intention actuelle
      // ----------------------------------------------

      currentIntent:
        current.intent ?? null,

      detectedCurrentIntent:
        currentIntent ?? null,

      // ----------------------------------------------
      // Etat précédent
      // ----------------------------------------------

      previousPendingAction:
        previousPendingAction,

      previousConversationStep:
        previousConversationStep,

      // ----------------------------------------------
      // Décision de machine à états
      // ----------------------------------------------

      hasExplicitBusinessIntent,

      explicitRestart,

      explicitCreateRestart,

      explicitRescheduleRestart,

      explicitCancelRestart,

      explicitGetRestart,

      actionChanged,

      startingNewAction,

      continuingPreviousAction,

      slotSelectionFromAvailability,

      // ----------------------------------------------
      // Anciennes valeurs
      // ----------------------------------------------

      previousService:
        previous.service ?? null,

      previousSite:
        previous.site ?? null,

      previousDateDebut:
        previous.date_debut ?? null,

      previousDateFin:
        previous.date_fin ?? null,

      previousToken:
        previous.token ?? null,

      previousAvailableSlotsCount:
        previousAvailableSlots.length,

      // ----------------------------------------------
      // Sélection
      // ----------------------------------------------

      selectedSlotIndex:
        selectedSlotIndex ?? null,

      selectedSlotFound:
        !!selectedSlot,

      // ----------------------------------------------
      // Valeurs finales
      // ----------------------------------------------

      resolvedService:
        service ?? null,

      resolvedSite:
        site ?? null,

      resolvedDateDebut:
        dateDebut ?? null,

      resolvedDateFin:
        dateFin ?? null,

      resolvedToken:
        token ?? null,

      resolvedSlotId:
        slotId ?? null,

      resolvedNewSlotId:
        newSlotId ?? null,

      finalIntent:
        intent
    }
  }
}];

const response =
  $('Préparer réponse disponibilité').item.json;

return [{
  json: {
    type: response.type ?? 'availability',
    title: response.title ?? 'Créneaux disponibles',
    slots: response.slots ?? [],
    availableSlots: response.availableSlots ?? [],
    text: response.text ?? "Voici les créneaux disponibles."
  }
}];

const x = { ...$json };

// ======================================================
// 1. ETAT PRECEDENT
// ======================================================
//
// IMPORTANT :
// previous sert principalement à connaître l'étape
// précédente de la machine à états.
//
// Les données métier (service, site, dates, token...)
// viennent en priorité de x, c'est-à-dire de
// "Fusionner état conversation".
//
// ======================================================

let previous = {};

try {
  previous =
    $('Joindre tentative de session').item.json ?? {};
} catch (e) {
  try {
    previous =
      $('Charger état conversation').item.json ?? {};
  } catch (e2) {
    previous = {};
  }
}

// ======================================================
// 2. PARSER DU MESSAGE COURANT
// ======================================================

let parserCurrent = {};
let createDecision = null;
let modifyField = null;
let skipCreateProgression = false;

try {
  parserCurrent =
    $('Parser intention').item.json ?? {};
} catch (e) {
  parserCurrent = {};
}

createDecision = parserCurrent.createDecision || null;
modifyField = parserCurrent.modifyField || null;
if (createDecision && createDecision !== 'INSERT') {
  skipCreateProgression = true;
}

// ======================================================
// 3. UTILITAIRES
// ======================================================

function hasValue(value) {
  return (
    value !== null &&
    value !== undefined &&
    value !== '' &&
    value !== 'null' &&
    value !== 'undefined'
  );
}

function isValidUUID(value) {
  if (!value) {
    return false;
  }

  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
    .test(String(value).trim());
}

function isValidEmail(value) {
  if (!value) {
    return false;
  }

  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    .test(String(value).trim());
}

function normalizePhone(value) {
  if (!value) {
    return null;
  }

  return String(value)
    .replace(/[^\d+]/g, '')
    .trim();
}

function isValidPhone(value) {
  const normalized =
    normalizePhone(value);

  if (!normalized) {
    return false;
  }

  return normalized
    .replace(/\D/g, '')
    .length >= 8;
}

function extractUUIDFromMessage(value) {
  if (!value) {
    return null;
  }

  const match =
    String(value).match(
      /\b[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\b/i
    );

  return match?.[0] ?? null;
}

function isQuestion(value) {
  if (!value) {
    return false;
  }

  return (
    value.includes('?') ||
    /^(quoi|comment|quelles?|quels?|pourquoi|où|ou|combien|de quelles?|de quels?)/i
      .test(value.trim())
  );
}

function normalizeSlots(value) {
  if (!value) {
    return [];
  }

  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed =
        JSON.parse(value);

      return Array.isArray(parsed)
        ? parsed
        : [];
    } catch (e) {
      return [];
    }
  }

  return [];
}

// ======================================================
// 4. MESSAGE COURANT
// ======================================================

const message =
  String(
    x.originalMessage ??
    parserCurrent.originalMessage ??
    ''
  ).trim();

const messageLower =
  message.toLowerCase();

// ======================================================
// 5. INTENTION COURANTE
// ======================================================

const businessIntents = [
  'CREATE_APPOINTMENT',
  'GET_APPOINTMENT',
  'CANCEL_APPOINTMENT',
  'RESCHEDULE_APPOINTMENT'
];

const parserIntent =
  parserCurrent.intent ??
  x.llmIntent ??
  x.intent ??
  null;

const currentIntent =
  x.intent ??
  parserIntent ??
  'GENERAL';

const previousPendingAction =
  previous.pending_action ??
  null;

const previousConversationStep =
  previous.conversation_step ??
  null;

const hasExplicitBusinessIntent =
  businessIntents.includes(parserIntent);

// ======================================================
// 6. INFORMATION FOURNIE PAR FUSIONNER ETAT
// ======================================================
//
// "Fusionner état conversation" sait maintenant détecter
// les redémarrages explicites.
//
// On récupère donc son diagnostic au lieu de refaire
// une deuxième fusion contradictoire.
//
// ======================================================

const fusionDebug =
  x.memoryDebug ?? {};

const fusionActionChanged =
  fusionDebug.actionChanged === true;

const fusionExplicitRestart =
  fusionDebug.explicitRestart === true;

const fusionStartingNewAction =
  fusionDebug.startingNewAction === true;

const newBusinessAction =
  fusionActionChanged ||
  fusionExplicitRestart ||
  fusionStartingNewAction;

// ======================================================
// 7. DONNEES METIER
// ======================================================
//
// REGLE FONDAMENTALE :
//
// x est la source de vérité.
//
// PAS :
//
// x.site ?? previous.site
//
// car cela réinjecterait les anciennes données que
// "Fusionner état conversation" vient volontairement
// d'effacer.
//
// ======================================================

let intent =
  currentIntent;

let pendingAction =
  x.pendingAction ??
  null;

let conversationStep =
  x.conversationStep ??
  null;

// ------------------------------------------------------
// Identifiants
// ------------------------------------------------------

let token =
  x.token ?? null;

let slotId =
  x.slotId ?? null;

let newSlotId =
  x.newSlotId ?? null;

// ------------------------------------------------------
// Critères
// ------------------------------------------------------

let service =
  x.service ?? null;

let site =
  x.site ?? null;

let dateDebut =
  x.dateDebut ?? null;

let dateFin =
  x.dateFin ?? null;

// ------------------------------------------------------
// Informations personnelles
// ------------------------------------------------------

let nom =
  x.nom ?? null;

let prenom =
  x.prenom ?? null;

let email =
  x.email ?? null;

let telephone =
  x.telephone ?? null;

// ------------------------------------------------------
// Créneaux
// ------------------------------------------------------

let selectedSlotIndex =
  x.selectedSlotIndex ??
  parserCurrent.selectedSlotIndex ??
  null;

let availableSlots =
  normalizeSlots(
    x.availableSlots ??
    x.available_slots ??
    []
  );

let selectedSlot =
  x.selectedSlot ?? null;

// ======================================================
// 8. DETERMINER L'ACTION ACTIVE
// ======================================================
//
// Si Fusionner état conversation indique une nouvelle
// action, on démarre avec l'intention actuelle.
//
// Sinon, une action précédente peut continuer.
//
// ======================================================

if (newBusinessAction) {

  pendingAction =
    businessIntents.includes(currentIntent)
      ? currentIntent
      : null;

  conversationStep =
    null;
}

else if (
  previousPendingAction &&
  businessIntents.includes(previousPendingAction)
) {

  pendingAction =
    previousPendingAction;

  // On conserve uniquement l'étape de conversation.
  // PAS les anciennes données métier.

  conversationStep =
    previousConversationStep ??
    conversationStep ??
    null;
}

else if (
  businessIntents.includes(currentIntent)
) {

  pendingAction =
    currentIntent;
}

// ======================================================
// 9. GET_APPOINTMENT
// ======================================================

if (
  pendingAction === 'GET_APPOINTMENT'
) {

  intent =
    'GET_APPOINTMENT';

  // ----------------------------------------------------
  // Si nous attendons le token, regarder le message
  // courant.
  // ----------------------------------------------------

  if (
    conversationStep === 'ASK_TOKEN' ||
    !conversationStep
  ) {

    const candidate =
      parserCurrent.token ??
      extractUUIDFromMessage(message) ??
      token;

    if (
      candidate &&
      isValidUUID(candidate)
    ) {

      token =
        String(candidate).trim();

      slotId =
        null;

      newSlotId =
        null;

      conversationStep =
        'READY_GET_APPOINTMENT';

    } else {

      token =
        null;

      conversationStep =
        'ASK_TOKEN';
    }
  }

  else if (
    token &&
    isValidUUID(token)
  ) {

    conversationStep =
      'READY_GET_APPOINTMENT';
  }

  else {

    conversationStep =
      'ASK_TOKEN';
  }
}

// ======================================================
// 10. CANCEL_APPOINTMENT
// ======================================================

else if (
  pendingAction === 'CANCEL_APPOINTMENT'
) {

  intent =
    'CANCEL_APPOINTMENT';

  slotId =
    null;

  newSlotId =
    null;

  // ----------------------------------------------------
  // Confirmation déjà demandée
  // ----------------------------------------------------

  if (
    conversationStep ===
      'ASK_CANCEL_CONFIRMATION'
  ) {

    conversationStep =
      'ASK_CANCEL_CONFIRMATION';
  }

  // ----------------------------------------------------
  // Sinon obtenir le token
  // ----------------------------------------------------

  else {

    const candidate =
      parserCurrent.token ??
      extractUUIDFromMessage(message) ??
      token;

    if (
      candidate &&
      isValidUUID(candidate)
    ) {

      token =
        String(candidate).trim();

      conversationStep =
        'READY_CANCEL_LOOKUP';

    } else {

      token =
        null;

      conversationStep =
        'ASK_TOKEN';
    }
  }
}

// ======================================================
// 11. RESCHEDULE_APPOINTMENT
// ======================================================

else if (
  pendingAction === 'RESCHEDULE_APPOINTMENT'
) {

  intent =
    'RESCHEDULE_APPOINTMENT';

  // RESCHEDULE n'utilise jamais slotId.

  slotId =
    null;

  // ----------------------------------------------------
  // 11.1 Nouvelle replanification
  // ----------------------------------------------------

  if (!conversationStep) {

    if (
      token &&
      isValidUUID(token)
    ) {

      conversationStep =
        'READY_RESCHEDULE_TOKEN';

    } else {

      const candidate =
        parserCurrent.token ??
        extractUUIDFromMessage(message);

      if (
        candidate &&
        isValidUUID(candidate)
      ) {

        token =
          String(candidate).trim();

        conversationStep =
          'READY_RESCHEDULE_TOKEN';

      } else {

        token =
          null;

        conversationStep =
          'ASK_RESCHEDULE_TOKEN';
      }
    }
  }

  // ----------------------------------------------------
  // 11.2 Token attendu
  // ----------------------------------------------------

  else if (
    conversationStep === 'ASK_TOKEN' ||
    conversationStep === 'ASK_RESCHEDULE_TOKEN'
  ) {

    const candidate =
      parserCurrent.token ??
      extractUUIDFromMessage(message) ??
      token;

    if (
      candidate &&
      isValidUUID(candidate)
    ) {

      token =
        String(candidate).trim();

      newSlotId =
        null;

      conversationStep =
        'READY_RESCHEDULE_TOKEN';

    } else {

      conversationStep =
        'ASK_RESCHEDULE_TOKEN';
    }
  }

  // ----------------------------------------------------
  // 11.3 Token prêt
  // ----------------------------------------------------

  else if (
    conversationStep === 'READY_RESCHEDULE_TOKEN'
  ) {

    if (
      !token ||
      !isValidUUID(token)
    ) {

      conversationStep =
        'ASK_RESCHEDULE_TOKEN';
    }
  }

  // ----------------------------------------------------
  // 11.4 Nouvelle période attendue
  // ----------------------------------------------------

  else if (
    conversationStep ===
      'ASK_RESCHEDULE_DATE_RANGE'
  ) {

    const newDateDebut =
      parserCurrent.dateDebut ??
      dateDebut ??
      null;

    const newDateFin =
      parserCurrent.dateFin ??
      dateFin ??
      null;

    if (
      newDateDebut &&
      newDateFin
    ) {

      dateDebut =
        newDateDebut;

      dateFin =
        newDateFin;

      conversationStep =
        'READY_RESCHEDULE_SEARCH';

    } else {

      conversationStep =
        'ASK_RESCHEDULE_DATE_RANGE';
    }
  }

  // ----------------------------------------------------
  // 11.5 Recherche prête
  // ----------------------------------------------------

  else if (
    conversationStep ===
      'READY_RESCHEDULE_SEARCH'
  ) {

    if (
      !dateDebut ||
      !dateFin
    ) {

      conversationStep =
        'ASK_RESCHEDULE_DATE_RANGE';
    }
  }

  // ----------------------------------------------------
  // 11.6 Choix d'un nouveau créneau
  // ----------------------------------------------------

  else if (
    conversationStep ===
      'ASK_RESCHEDULE_SLOT'
  ) {

    let choice =
      parserCurrent.selectedSlotIndex ??
      selectedSlotIndex ??
      null;

    if (
      choice === null ||
      choice === undefined
    ) {

      const match =
        message.match(/\b(\d{1,2})\b/);

      if (match) {
        choice =
          Number(match[1]);
      }
    }

    if (
      choice !== null &&
      choice !== undefined
    ) {

      selectedSlotIndex =
        Number(choice);
    }

    if (
      !selectedSlot &&
      Number.isInteger(selectedSlotIndex) &&
      selectedSlotIndex >= 1 &&
      selectedSlotIndex <= availableSlots.length
    ) {

      selectedSlot =
        availableSlots[selectedSlotIndex - 1];
    }

    const candidateNewSlotId =
      selectedSlot?.id ??
      selectedSlot?.slotId ??
      parserCurrent.newSlotId ??
      newSlotId ??
      null;

    if (
      candidateNewSlotId &&
      isValidUUID(candidateNewSlotId)
    ) {

      newSlotId =
        String(candidateNewSlotId).trim();

      conversationStep =
        'ASK_RESCHEDULE_CONFIRMATION';

    } else {

      newSlotId =
        null;

      conversationStep =
        'ASK_RESCHEDULE_SLOT';
    }
  }

  // ----------------------------------------------------
  // 11.7 Confirmation attendue
  // ----------------------------------------------------

  else if (
    conversationStep ===
      'ASK_RESCHEDULE_CONFIRMATION'
  ) {

    conversationStep =
      'ASK_RESCHEDULE_CONFIRMATION';
  }
}

// ======================================================
// 12. CREATE_APPOINTMENT
// ======================================================

else if (
  pendingAction === 'CREATE_APPOINTMENT'
) {

  intent =
    'CREATE_APPOINTMENT';

  // CREATE n'utilise jamais le token de gestion
  // d'un rendez-vous existant.

  token =
    null;

  newSlotId =
    null;

  // ----------------------------------------------------
  // 12.1 Résoudre un slot UUID explicitement fourni
  // ----------------------------------------------------

  if (!slotId) {

    const candidateSlot =
      parserCurrent.slotId ??
      null;

    if (
      candidateSlot &&
      isValidUUID(candidateSlot)
    ) {

      slotId =
        String(candidateSlot).trim();
    }
  }

  // ----------------------------------------------------
  // 12.2 "Je prends le 2"
  // ----------------------------------------------------

  if (
    !slotId &&
    selectedSlotIndex !== null &&
    selectedSlotIndex !== undefined &&
    availableSlots.length > 0
  ) {

    const index =
      Number(selectedSlotIndex) - 1;

    if (
      Number.isInteger(index) &&
      index >= 0 &&
      index < availableSlots.length
    ) {

      selectedSlot =
        availableSlots[index];

      const candidate =
        selectedSlot?.id ??
        selectedSlot?.slotId ??
        null;

      if (
        candidate &&
        isValidUUID(candidate)
      ) {

        slotId =
          String(candidate).trim();
      }
    }
  }

  // ----------------------------------------------------
  // 12.3 Coordonnées personnelles
  // ----------------------------------------------------

  if (slotId) {

    // NOM

    if (
      conversationStep === 'ASK_NOM' &&
      message &&
      !nom &&
      !isQuestion(message)
    ) {

      const candidate =
        parserCurrent.nom ??
        message;

      if (
        candidate &&
        String(candidate).trim().length >= 2
      ) {

        nom =
          String(candidate).trim();
      }
    }

    // PRENOM

    else if (
      conversationStep === 'ASK_PRENOM' &&
      message &&
      !prenom &&
      !isQuestion(message)
    ) {

      const candidate =
        parserCurrent.prenom ??
        message;

      if (
        candidate &&
        String(candidate).trim().length >= 2
      ) {

        prenom =
          String(candidate).trim();
      }
    }

    // EMAIL

    else if (
      conversationStep === 'ASK_EMAIL' &&
      message &&
      !isValidEmail(email)
    ) {

      const candidate =
        parserCurrent.email ??
        message.match(
          /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i
        )?.[0] ??
        null;

      if (
        candidate &&
        isValidEmail(candidate)
      ) {

        email =
          String(candidate).trim();
      }
    }

    // TELEPHONE

    else if (
      conversationStep === 'ASK_TELEPHONE' &&
      message &&
      !isValidPhone(telephone)
    ) {

      const candidate =
        parserCurrent.telephone ??
        message.match(
          /(?:\+\d{7,15}|\b\d{8,15}\b)/
        )?.[0] ??
        null;

      if (
        candidate &&
        isValidPhone(candidate)
      ) {

        telephone =
          normalizePhone(candidate);
      }
    }
  }

  // ====================================================
  // 12.4 CALCUL DE L'ETAPE CREATE
  // ====================================================

  if (skipCreateProgression) {
    intent = 'CREATE_APPOINTMENT';
    if (createDecision === 'RECALL') conversationStep = 'CREATE_RECALL';
    else if (createDecision === 'RESUME') conversationStep = 'CREATE_UNCERTAIN';
    else conversationStep = 'AWAIT_CREATE_CONFIRMATION';
  }

  else if (slotId) {

    if (!nom) {

      conversationStep =
        'ASK_NOM';

    } else if (!prenom) {

      conversationStep =
        'ASK_PRENOM';

    } else if (!isValidEmail(email)) {

      conversationStep =
        'ASK_EMAIL';

    } else if (!isValidPhone(telephone)) {

      conversationStep =
        'ASK_TELEPHONE';

    } else {

      conversationStep =
        'AWAIT_CREATE_CONFIRMATION';
      if (previous.conversation_step !== 'AWAIT_CREATE_CONFIRMATION') {
        createDecision = 'INSERT';
      }
    }
  }

  // ----------------------------------------------------
  // Pas encore de créneau
  // ----------------------------------------------------

  else {

    if (!service) {

      conversationStep =
        'ASK_CREATE_SERVICE';

      intent =
        'CREATE_APPOINTMENT';
    }

    else if (!site) {

      conversationStep =
        'ASK_CREATE_SITE';

      intent =
        'CREATE_APPOINTMENT';
    }

    else if (
      !dateDebut ||
      !dateFin
    ) {

      conversationStep =
        'ASK_CREATE_DATE_RANGE';

      intent =
        'CREATE_APPOINTMENT';
    }

    else {

      conversationStep =
        'READY_CREATE_SEARCH';

      intent =
        'GET_AVAILABILITY';
    }
  }
}

// ======================================================
// 13. GET_AVAILABILITY SANS ACTION CREATE
// ======================================================

else if (
  currentIntent === 'GET_AVAILABILITY'
) {

  intent =
    'GET_AVAILABILITY';

  pendingAction =
    'GET_AVAILABILITY';

  conversationStep =
    null;
}

// ======================================================
// 14. GENERAL
// ======================================================

else {

  intent =
    currentIntent ??
    'GENERAL';

  pendingAction =
    null;

  conversationStep =
    null;
}

// ======================================================
// 15. NORMALISATION TELEPHONE
// ======================================================

if (
  telephone &&
  isValidPhone(telephone)
) {

  telephone =
    normalizePhone(telephone);
}

// ======================================================
// 16. FORÇAGE FINAL DES INTENTIONS
// ======================================================

if (
  pendingAction === 'RESCHEDULE_APPOINTMENT'
) {

  intent =
    'RESCHEDULE_APPOINTMENT';

  slotId =
    null;
}

else if (
  pendingAction === 'CANCEL_APPOINTMENT'
) {

  intent =
    'CANCEL_APPOINTMENT';
}

else if (
  pendingAction === 'GET_APPOINTMENT'
) {

  intent =
    'GET_APPOINTMENT';
}

else if (
  pendingAction === 'CREATE_APPOINTMENT'
) {

  if (
    conversationStep === 'READY_CREATE_SEARCH' &&
    !slotId &&
    service &&
    site &&
    dateDebut &&
    dateFin
  ) {

    intent =
      'GET_AVAILABILITY';

  } else {

    intent =
      'CREATE_APPOINTMENT';
  }
}

// ======================================================
// 17. ETATS READY
// ======================================================

const creationServicePending =
  pendingAction === 'CREATE_APPOINTMENT' &&
  conversationStep === 'ASK_CREATE_SERVICE';

const creationSitePending =
  pendingAction === 'CREATE_APPOINTMENT' &&
  conversationStep === 'ASK_CREATE_SITE';

const creationDateRangePending =
  pendingAction === 'CREATE_APPOINTMENT' &&
  conversationStep === 'ASK_CREATE_DATE_RANGE';

const creationSlotPending =
  pendingAction === 'CREATE_APPOINTMENT' &&
  conversationStep === 'ASK_CREATE_SLOT' &&
  !slotId;

const creationSearchReady =
  pendingAction === 'CREATE_APPOINTMENT' &&
  conversationStep === 'READY_CREATE_SEARCH' &&
  !slotId &&
  !!service &&
  !!site &&
  !!dateDebut &&
  !!dateFin;

const creationComplete =
  pendingAction === 'CREATE_APPOINTMENT' &&
  conversationStep === 'READY_CREATE' &&
  !!slotId &&
  !!nom &&
  !!prenom &&
  isValidEmail(email) &&
  isValidPhone(telephone);

const getAppointmentReady =
  pendingAction === 'GET_APPOINTMENT' &&
  conversationStep === 'READY_GET_APPOINTMENT' &&
  isValidUUID(token);

const cancelLookupReady =
  pendingAction === 'CANCEL_APPOINTMENT' &&
  conversationStep === 'READY_CANCEL_LOOKUP' &&
  isValidUUID(token);

const cancelConfirmationPending =
  pendingAction === 'CANCEL_APPOINTMENT' &&
  conversationStep === 'ASK_CANCEL_CONFIRMATION';

const rescheduleTokenReady =
  pendingAction === 'RESCHEDULE_APPOINTMENT' &&
  conversationStep === 'READY_RESCHEDULE_TOKEN' &&
  isValidUUID(token);

const rescheduleDateRangePending =
  pendingAction === 'RESCHEDULE_APPOINTMENT' &&
  conversationStep === 'ASK_RESCHEDULE_DATE_RANGE';

const rescheduleSearchReady =
  pendingAction === 'RESCHEDULE_APPOINTMENT' &&
  conversationStep === 'READY_RESCHEDULE_SEARCH' &&
  isValidUUID(token) &&
  !!service &&
  !!site &&
  !!dateDebut &&
  !!dateFin;

const rescheduleSlotPending =
  pendingAction === 'RESCHEDULE_APPOINTMENT' &&
  conversationStep === 'ASK_RESCHEDULE_SLOT';

const rescheduleConfirmationPending =
  pendingAction === 'RESCHEDULE_APPOINTMENT' &&
  conversationStep === 'ASK_RESCHEDULE_CONFIRMATION';

// ======================================================
// 18. RESULTAT
// ======================================================

return [{
  json: {

    ...x,

    // --------------------------------------------------
    // Etat métier
    // --------------------------------------------------

    intent,

    service,
    site,

    dateDebut,
    dateFin,

    token,
    slotId,
    newSlotId,

    selectedSlotIndex,
    selectedSlot,

    nom,
    prenom,
    email,
    telephone,

    availableSlots,

    pendingAction,
    conversationStep,
    createDecision,
    modifyField,

    // --------------------------------------------------
    // Etats calculés
    // --------------------------------------------------

    stateReady: {

      createServicePending:
        creationServicePending,

      createSitePending:
        creationSitePending,

      createDateRangePending:
        creationDateRangePending,

      createSlotPending:
        creationSlotPending,

      createSearch:
        creationSearchReady,

      createAppointment:
        creationComplete,

      getAppointment:
        getAppointmentReady,

      cancelLookup:
        cancelLookupReady,

      cancelConfirmationPending:
        cancelConfirmationPending,

      rescheduleToken:
        rescheduleTokenReady,

      rescheduleDateRangePending:
        rescheduleDateRangePending,

      rescheduleSearch:
        rescheduleSearchReady,

      rescheduleSlotPending:
        rescheduleSlotPending,

      rescheduleConfirmationPending:
        rescheduleConfirmationPending
    },

    // ==================================================
    // DEBUG TEMPORAIRE
    // ==================================================

    collectionDebug: {

      rawXIntent:
        x.intent ?? null,

      rawLlmIntent:
        x.llmIntent ?? null,

      parserIntent:
        parserCurrent.intent ?? null,

      currentIntent,

      previousIntent:
        previous.intent ?? null,

      previousPendingAction:
        previousPendingAction,

      previousConversationStep:
        previousConversationStep,

      // ----------------------------------------------
      // Diagnostic venant de Fusionner état
      // ----------------------------------------------

      fusionActionChanged,

      fusionExplicitRestart,

      fusionStartingNewAction,

      newBusinessAction,

      // ----------------------------------------------
      // Etat final
      // ----------------------------------------------

      finalIntent:
        intent,

      finalPendingAction:
        pendingAction,

      finalConversationStep:
        conversationStep,

      resolvedService:
        service ?? null,

      resolvedSite:
        site ?? null,

      resolvedDateDebut:
        dateDebut ?? null,

      resolvedDateFin:
        dateFin ?? null,

      resolvedToken:
        token ?? null,

      resolvedSlotId:
        slotId ?? null,

      resolvedNewSlotId:
        newSlotId ?? null,

      selectedSlotIndex:
        selectedSlotIndex ?? null,

      availableSlotsCount:
        availableSlots.length,

      // ----------------------------------------------
      // Etats
      // ----------------------------------------------

      creationServicePending,
      creationSitePending,
      creationDateRangePending,
      creationSlotPending,
      creationSearchReady,
      creationComplete,

      getAppointmentReady,

      cancelLookupReady,
      cancelConfirmationPending,

      rescheduleTokenReady,
      rescheduleDateRangePending,
      rescheduleSearchReady,
      rescheduleSlotPending,
      rescheduleConfirmationPending
    }
  }
}];

const x = $json;

const missing = [];

// ------------------------------------------------------
// Vérification des champs obligatoires
// ------------------------------------------------------

if (!x.slotId) {
  missing.push("le créneau choisi");
}

if (!x.nom) {
  missing.push("le nom");
}

if (!x.prenom) {
  missing.push("le prénom");
}

if (!x.email) {
  missing.push("l'adresse e-mail");
}

