    .replace(/[\u0300-\u036f]/g, '')
    .trim();

// ------------------------------------------------------
// Expressions positives
// ------------------------------------------------------

const positivePatterns = [
  /^oui$/,
  /^oui\s*[!.]?$/,
  /^yes$/,
  /^ok$/,
  /^d'accord$/,
  /^daccord$/,
  /^je confirme$/,
  /^confirme$/,
  /^confirmer$/,
