  return d.toLocaleTimeString('fr-FR', {
    timeZone: 'Europe/Paris',
    hour: '2-digit',
    minute: '2-digit'
  });
}

const date =
  formatDate(selected?.debut);

const heureDebut =
  formatTime(selected?.debut);

const heureFin =
  formatTime(selected?.fin);

let text =
  "⚠️ **Confirmation de replanification**\n\n";

if (date) {
  text += `📅 **Nouvelle date :** ${date}\n`;
}

if (heureDebut) {
  text += `🕒 **Nouvel horaire :** ${heureDebut}`;

  if (heureFin) {
    text += ` – ${heureFin}`;
  }

  text += "\n";
}

if (x.service) {
  text += `🛂 **Service :** ${x.service}\n`;
}

if (x.site) {
  text += `📍 **Site :** ${x.site}\n`;
}

text +=
  "\n❓ Confirmez-vous la replanification de ce rendez-vous ?\n\n" +
  "👉 Répondez simplement **Oui** ou **Non**.";

return [{
  json: {
    ...x,

    type:
      'reschedule_confirmation',

    success:
      true,

    pendingAction:
      'RESCHEDULE_APPOINTMENT',

    conversationStep:
      'ASK_RESCHEDULE_CONFIRMATION',

    newSlotId,

    selectedSlot:
      selected,

    text
  }
}];

const x = { ...$json };

const message =
  String(
    x.originalMessage ??
    ''
  )
    .trim()
    .toLowerCase();

// ------------------------------------------------------
// Normalisation
// ------------------------------------------------------

const normalized = message
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[.!?;,]+/g, '')
  .trim();

// ------------------------------------------------------
// Réponses positives
// ------------------------------------------------------

const yesValues = [
  'oui',
  'o',
  'yes',
  'y',
  'ok',
  'okay',
  'daccord',
  "d'accord",
  'je confirme',
  'confirme',
  'je valide',
  'valider',
  'oui je confirme',
  'oui confirmer'
];

// ------------------------------------------------------
// Réponses négatives
// ------------------------------------------------------

const noValues = [
  'non',
  'n',
  'no',
  'annuler',
  'abandonner',
  'je refuse',
  'ne pas confirmer',
  'non merci'
];

let recognized = false;
let confirmed = null;

if (
  yesValues.includes(normalized) ||
  /^oui\b/.test(normalized)
) {
  recognized = true;
  confirmed = true;
}

else if (
  noValues.includes(normalized) ||
  /^non\b/.test(normalized)
) {
  recognized = true;
  confirmed = false;
}

return [{
  json: {
    ...x,

    confirmationRecognized: recognized,
    rescheduleConfirmed: confirmed,

    confirmationDebug: {
      originalMessage: message,
      normalized
    }
  }
}];

const x = $json;

return [{
  json: {
    ...x,

    pendingAction:
      'RESCHEDULE_APPOINTMENT',

    conversationStep:
      'ASK_RESCHEDULE_CONFIRMATION',

    text:
      "❓ Je n'ai pas compris votre réponse.\n\n" +
      "Confirmez-vous la replanification du rendez-vous ?\n\n" +
      "👉 Répondez simplement **Oui** ou **Non**."
  }
}];

const x = { ...$json };

// ============================================================
// Préparer appel replanification
// ============================================================

// Normalisation du token
const token =
  x.token
    ? String(x.token).trim()
    : null;

// Normalisation du nouveau créneau
const newSlotId =
  x.newSlotId
    ? String(x.newSlotId).trim()
    : null;

return [{
  json: {
    ...x,

    pendingAction: 'RESCHEDULE_APPOINTMENT',

    conversationStep: 'READY_RESCHEDULE',

    token,
    newSlotId
  }
}];

// ============================================================
// Restaurer réponse confirmation replanification
// ============================================================

const db = $input.first().json;

// ------------------------------------------------------------
// Récupérer la réponse préparée AVANT le noeud PostgreSQL
// ------------------------------------------------------------

let prepared = {};

try {
  prepared =
    $('Préparer confirmation replanification')
      .first()
      .json ?? {};
} catch (e) {
  prepared = {};
}

// ------------------------------------------------------------
// Récupération des valeurs importantes
// ------------------------------------------------------------

const sessionId =
  db.session_id ??
  prepared.sessionId ??
  null;

const token =
  db.token ??
  prepared.token ??
  null;

const newSlotId =
  db.new_slot_id ??
  prepared.newSlotId ??
  null;

const selectedSlot =
  prepared.selectedSlot ??
  null;

// ------------------------------------------------------------
// Texte déjà préparé
// ------------------------------------------------------------

let text =
  prepared.text ??
  null;

// ------------------------------------------------------------
// Fallback si le texte n'est plus disponible
// ------------------------------------------------------------

if (!text) {

  const service =
    prepared.service ??
    db.service ??
    null;

  const site =
    prepared.site ??
    db.site ??
    null;

  const date =
    selectedSlot?.date ??
    null;

  const heureDebut =
    selectedSlot?.heureDebut ??
    null;

  const heureFin =
    selectedSlot?.heureFin ??
    null;

  text =
    "⚠️ **Confirmation de replanification**\n\n";

  if (service) {
    text += `🛂 **Service :** ${service}\n`;
  }

  if (site) {
    text += `📍 **Site :** ${site}\n`;
  }

  if (date) {
    text += `📅 **Nouvelle date :** ${date}\n`;
  }

  if (heureDebut) {
    text += `🕒 **Nouvel horaire :** ${heureDebut}`;

    if (heureFin) {
      text += ` – ${heureFin}`;
    }

    text += "\n";
  }

  text +=
    "\n❓ Confirmez-vous la replanification de ce rendez-vous ?\n\n" +
    "👉 Répondez simplement **Oui** ou **Non**.";
}

// ------------------------------------------------------------
// Sortie finale vers le chat
// ------------------------------------------------------------

return [{
  json: {

    type:
      'reschedule_confirmation',

    success:
      true,

    sessionId,

    intent:
      'RESCHEDULE_APPOINTMENT',

    pendingAction:
      'RESCHEDULE_APPOINTMENT',

    conversationStep:
      'ASK_RESCHEDULE_CONFIRMATION',

    token,

    newSlotId,

    selectedSlot,

    text
  }
}];

const x = $json;

return [{
  json: {
    ...x,

    type:
      'reschedule_aborted',

    success:
      true,

    pendingAction:
      null,

    conversationStep:
      null,

    text:
      "✅ **Replanification abandonnée**\n\n" +
      "Votre rendez-vous actuel reste inchangé."
  }
}];

const trigger = $('Lorsqu\'un message de chat est reçu').item.json || {};
let previous = {};
try { previous = $('Charger état conversation').item.json ?? {}; } catch (e) { previous = {}; }
const row = $json || {};
const openAttempt = row.attempt_id ? {
  id: row.attempt_id,
  status: row.attempt_status,
  reference: row.appointment_reference || null,
  leaseUntil: row.lease_until || null,
  expiresAt: row.expires_at || null,
  resumeCount: row.resume_count
} : null;
return [{
  json: {
    ...previous,
    sessionId: previous.sessionId || previous.session_id || trigger.sessionId || null,
    openAttempt
  }
}];

const saved = $json;
let collected = {};
let joined = {};

try { collected = $('Gérer collecte progressive').item.json ?? {}; } catch (e) { collected = {}; }
try { joined = $('Joindre tentative de session').item.json ?? {}; } catch (e) { joined = {}; }

const decision = collected.createDecision || null;
const openAttempt = joined.openAttempt || null;
const status = openAttempt ? openAttempt.status : null;
const now = Date.now();
const leaseUntil = openAttempt && openAttempt.leaseUntil ? new Date(openAttempt.leaseUntil).getTime() : null;
const expiresAt = openAttempt && openAttempt.expiresAt ? new Date(openAttempt.expiresAt).getTime() : null;
const leaseExpired = leaseUntil !== null && leaseUntil <= now;
const waitExpired = expiresAt !== null && expiresAt <= now;

let attemptAction = 'COLLECT';

if (status === 'UNCERTAIN' || (status === 'SUBMITTING' && leaseExpired)) {
  attemptAction = 'RESUME';
} else if (status === 'SUBMITTING') {
  attemptAction = 'WAIT';
} else if (status === 'AWAITING_CONFIRMATION' && waitExpired) {
  attemptAction = 'EXPIRE';
} else if (status === 'AWAITING_CONFIRMATION' && decision === 'AFFIRM') {
  attemptAction = 'CLAIM';
} else if (status === 'AWAITING_CONFIRMATION' && decision === 'NEGATIVE') {
  attemptAction = 'ABANDON';
} else if (status === 'AWAITING_CONFIRMATION' && decision === 'MODIFY') {
  attemptAction = 'MODIFY';
} else if (status === 'AWAITING_CONFIRMATION' && decision === 'RESTART') {
  attemptAction = 'RESTART';
} else if (status === 'AWAITING_CONFIRMATION') {
  attemptAction = 'ASK';
} else if (decision === 'INSERT') {
  attemptAction = 'INSERT';
} else if (!status && (saved.conversationStep === 'AWAIT_CREATE_CONFIRMATION' || collected.conversationStep === 'AWAIT_CREATE_CONFIRMATION')) {
  attemptAction = 'RESET_STALE';
} else if (decision === 'RECALL' || (status === 'CONFIRMED' && decision === 'AFFIRM')) {
  attemptAction = 'RECALL';
} else if (decision === 'RESUME') {
  attemptAction = 'RESUME';
} else if (decision === 'EXPIRE') {
  attemptAction = 'EXPIRE';
}

return [{
  json: {
    sessionId: saved.sessionId || joined.sessionId || null,
    conversationStep: saved.conversationStep || collected.conversationStep || null,
    attemptAction,
    modifyField: collected.modifyField || null,
    openAttempt,
    reference: saved.reference || (openAttempt && openAttempt.reference) || null,
    ready: false,
    claimAcquired: false
  }
}];

let collected = {};
try { collected = $('Gérer collecte progressive').item.json ?? {}; } catch (e) { collected = {}; }

function nfc(value) {
  return String(value ?? '').trim().normalize('NFC');
}

const idempotencyKey = String($json.idempotencyKey || '');
const attemptId = String($json.attemptId || '');
const keyOk = /^rec008-[0-9a-f]{64}$/.test(idempotencyKey);
const idOk = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(attemptId);
if (!keyOk || !idOk) {
  return [{ json: { frozenReady: false, sessionId: collected.sessionId || null } }];
}

const slots = Array.isArray(collected.availableSlots) ? collected.availableSlots : [];
const remembered = String(collected.slotId || '').trim().toLowerCase();
const slot = slots.find((item) => String(item.id || item.slotId || '').trim().toLowerCase() === remembered);
const slotId = String((slot && (slot.id || slot.slotId)) || collected.slotId || '').trim().toLowerCase();
const payload = {
  slotId,
  nom: nfc(collected.nom),
  prenom: nfc(collected.prenom),
  email: String(collected.email || '').trim(),
  telephone: String(collected.telephone || '').trim(),
  numeroDocument: '',
  langue: 'fr',
  cleIdempotence: idempotencyKey
};
const canonical = JSON.stringify(payload);
return [{
  json: {
    frozenReady: true,
    attemptId,
    sessionId: collected.sessionId || null,
    idempotencyKey,
    requestPayload: payload,
    canonical
  }
}];

if (!$json.attempt_id) {
  return [{ json: { type: 'create_not_frozen', text: 'La demande n\'a pas été enregistrée. Aucun rendez-vous n\'est créé.' } }];
}
let collected = {};
try { collected = $('Gérer collecte progressive').item.json ?? {}; } catch (e) { collected = {}; }
const slots = Array.isArray(collected.availableSlots) ? collected.availableSlots : [];
const slotId = String(collected.slotId || '').toLowerCase();
const slot = slots.find((item) => String(item.id || '').toLowerCase() === slotId) || {};
const debut = slot.debut ? new Date(slot.debut) : null;
const fin = slot.fin ? new Date(slot.fin) : null;
const dateLabel = debut && !Number.isNaN(debut.getTime())
  ? debut.toLocaleDateString('fr-FR', { timeZone: 'Europe/Paris', weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' })
  : 'date mémorisée';
const heure = debut && fin && !Number.isNaN(debut.getTime())
  ? debut.toLocaleTimeString('fr-FR', { timeZone: 'Europe/Paris', hour: '2-digit', minute: '2-digit' }) + ' – ' + fin.toLocaleTimeString('fr-FR', { timeZone: 'Europe/Paris', hour: '2-digit', minute: '2-digit' })
  : 'horaire mémorisé';
const text = [
  'Veuillez confirmer la création du rendez-vous.',
  '',
  'Service : ' + (collected.service || slot.service || 'non renseigné'),
  'Site : ' + (collected.site || slot.site || 'non renseigné'),
  'Date : ' + dateLabel,
  'Heure : ' + heure,
  'Nom : ' + (collected.nom || ''),
  'Prénom : ' + (collected.prenom || ''),
  'Adresse : ' + (collected.email || ''),
  'Téléphone : ' + (collected.telephone || ''),
  '',
  'Répondez exactement oui pour créer ce rendez-vous, non pour abandonner, ou indiquez le champ à modifier.'
].join('\n');
return [{ json: { type: 'create_appointment_question', conversationStep: 'AWAIT_CREATE_CONFIRMATION', text } }];

const attempt = $json.openAttempt || {};
return [{
  json: {
    attemptId: attempt.id,
    sessionId: $json.sessionId,
    modifyField: $json.modifyField || null,
    reference: $json.reference || attempt.reference || null
  }
}];

const attempt = $json.openAttempt || {};
return [{
  json: {
    attemptId: attempt.id,
    sessionId: $json.sessionId,
    modifyField: $json.modifyField || null,
    reference: $json.reference || attempt.reference || null
  }
}];

const value = $json.acquired ?? $json.closed ?? $json.marked ?? false;
const normalized = value === true || value === 't' || value === 'true';
return [{ json: { ...$json, acquired: normalized, closed: normalized, marked: normalized } }];

const acquired = $json.acquired === true;
let payload = $json.request_payload;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = null; }
}
const key = $json.idempotency_key;
const leaseOwner = String($json.lease_owner || '');
const ownerOk = /^own-[0-9a-f]{32}$/.test(leaseOwner);
if (!acquired || !payload || !key || payload.cleIdempotence !== key || !ownerOk) {
  return [{ json: { httpReady: false, text: 'La confirmation n\'a pas obtenu le droit d\'envoyer la demande. Aucune nouvelle demande n\'est créée.' } }];
}
const frozenBody = JSON.stringify({
  slotId: String(payload.slotId || '').trim().toLowerCase(),
  nom: payload.nom,
  prenom: payload.prenom,
  email: payload.email,
  telephone: payload.telephone,
  numeroDocument: payload.numeroDocument ?? '',
  langue: payload.langue ?? 'fr',
  cleIdempotence: key
});
let prep = {};
try { prep = $('Préparer réclamation ou reprise').item.json ?? {}; } catch (e) { prep = {}; }
if (!prep.attemptId) {
  try { prep = $('Préparer reprise').item.json ?? {}; } catch (e) { prep = prep || {}; }
}
return [{
  json: {
    httpReady: true,
    ready: true,
    claimAcquired: true,
    frozenBody,
    attemptId: $json.attempt_id || prep.attemptId,
    sessionId: prep.sessionId,
    leaseOwner
  }
}];

let prep = {};
try { prep = $('Appliquer corps gagnant').item.json ?? {}; } catch (e) { prep = {}; }
let status = Number($json.statusCode || 0);
let body = $json.body ?? $json.data ?? null;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = null; }
}
const errorCode = body && body.error && body.error.code;
const message = body && (body.message || (body.error && body.error.message));
let httpOutcome = 'UNCERTAIN';
if (!status || body === null) {
  httpOutcome = 'UNCERTAIN';
} else if (status === 201 || (status === 200 && body && body.replayed === true && body.created === false)) {
  httpOutcome = 'CONFIRMED';
} else if (status === 400) {
  httpOutcome = 'REJECTED';
} else if (status === 409 && errorCode === 'IDEMPOTENCY_KEY_CONFLICT') {
  httpOutcome = 'REJECTED';
} else if (status === 409 && message === 'Créneau introuvable ou complet') {
  httpOutcome = 'SLOT_UNAVAILABLE';
} else {
  httpOutcome = 'UNCERTAIN';
}
const appointment = body && body.appointment ? body.appointment : null;
return [{
  json: {
    httpOutcome,
    attemptId: prep.attemptId,
    sessionId: prep.sessionId,
    leaseOwner: prep.leaseOwner,
    appointmentId: appointment && appointment.id ? appointment.id : null,
    appointmentReference: appointment && appointment.reference ? appointment.reference : null,
    appointment: appointment,
    success: body && body.success === true,
    created: body && body.created === true,
    replayed: body && body.replayed === true
  }
}];

let prep = {};
try { prep = $('Appliquer corps gagnant').item.json ?? {}; } catch (e) { prep = {}; }
return [{
  json: {
    httpOutcome: 'UNCERTAIN',
    timeout: true,
    attemptId: prep.attemptId,
    sessionId: prep.sessionId,
    leaseOwner: prep.leaseOwner,
    text: 'Le résultat de la création n\'est pas connu. Cela ne prouve pas qu\'aucun rendez-vous a été créé. La même demande sera rejouée au prochain message, sans nouvelle clé.'
  }
}];

return [{
  json: {
    attemptId: $json.attemptId,
    sessionId: $json.sessionId,
    leaseOwner: $json.leaseOwner,
    appointmentId: $json.appointmentId,
    appointmentReference: $json.appointmentReference,
    appointment: $json.appointment || null,
    replayed: $json.replayed === true
  }
}];

const value = $json.acquired ?? $json.closed ?? $json.marked ?? false;
const normalized = value === true || value === 't' || value === 'true';
let params = {};
try { params = $('Paramètres clôture confirmation').item.json ?? {}; } catch (e) { params = {}; }
return [{ json: { ...params, acquired: normalized, closed: normalized, marked: normalized } }];

const reference = $json.appointmentReference || ($json.appointment && $json.appointment.reference) || null;
const token = $json.appointment && ($json.appointment.token_gestion || $json.appointment.token);
let text = 'La réponse du service de création a été reçue, mais la clôture de la tentative n\'a pas été enregistrée. Aucune nouvelle demande n\'est créée.';
if (reference) text += ' Référence : ' + reference + '.';
if (token) text += ' Token de gestion : ' + token + '.';
text += ' Aucune nouvelle clé n\'est créée. Tant que le bail de 90 secondes reste ouvert, un nouveau message n\'envoie pas la demande. Après ce délai, la même demande peut être reprise.';
return [{ json: { type: 'create_close_uncertain', text } }];

parameters.query:
WITH input AS (
  SELECT $1::jsonb AS data
)
SELECT public.marquer_tentative_incertaine(
  (data->>'attemptId')::uuid,
  data->>'sessionId',
  data->>'leaseOwner'
) AS marked
FROM input;

parameters.jsCode:
const action = $json.attemptAction;
const steps = {
  nom: 'ASK_NOM',
  prenom: 'ASK_PRENOM',
  email: 'ASK_EMAIL',
  telephone: 'ASK_TELEPHONE',
  creneau: 'ASK_CREATE_SLOT'
};
let field = $json.modifyField || 'nom';
let conversationStep = steps[field] || 'ASK_NOM';
let clearDraft = false;
if (action === 'ABANDON') {
  field = 'all';
  conversationStep = null;
  clearDraft = true;
} else if (action === 'RESTART') {
  field = 'all';
  conversationStep = 'ASK_CREATE_SERVICE';
}
return [{
  json: {
    attemptId: ($json.openAttempt && $json.openAttempt.id) || null,
    sessionId: $json.sessionId,
    modifyField: field,
    conversationStep,
    clearDraft
  }
}];

const step = $json.conversationStep;
const questions = {
  ASK_NOM: 'Quel nom souhaitez-vous indiquer ?',
  ASK_PRENOM: 'Quel prénom souhaitez-vous indiquer ?',
  ASK_EMAIL: 'Quelle adresse e-mail souhaitez-vous indiquer ?',
  ASK_TELEPHONE: 'Quel numéro de téléphone souhaitez-vous indiquer ?',
  ASK_CREATE_SLOT: 'Quel autre créneau souhaitez-vous choisir ?',
  ASK_CREATE_SERVICE: 'La demande précédente est annulée. Pour quel service souhaitez-vous prendre rendez-vous ?'
};
return [{ json: { type: 'create_appointment_question', conversationStep: step, text: questions[step] || 'Indiquez la nouvelle information.' } }];

parameters.query:
SELECT
  gen_random_uuid()::text AS "attemptId",
  'rec008-' || encode(public.gen_random_bytes(32), 'hex') AS "idempotencyKey";
